/* eslint-disable no-shadow */
import React, { useState } from 'react'
import { axiosInstance } from 'services/globalInstance'
import { SectionHeader } from 'components/features/onboard/FlowScreens/common'
import { rollbar } from 'components/common/rollbar'
import { emailRegex } from 'Utils/helpers/commonUtils'
import { Form } from 'antd'
import styled from 'styled-components'
import { useRouter } from 'next/router'
import { InfoBox } from '../SignupSecondaryLayout'
import FlowLayout from '../FlowLayout'
import FlowNavButtons from '../FlowNavButtons'
import TextInput from '../TextInput'
import { focusInput } from '../FlowScreens/OrganizationApps'

const Wrapper = styled.div`
	display: flex;
	flex-direction: column;
	width: 100%;
	margin-bottom: 8px;
	margin-top: 24px;
`

export const ErrorText = styled.p`
  font-size: 14px !important;
  color: #f4584c !important;
  text-align: left !important;
`

export const lengthRegex = /^.{12,}$/
export const uppercaseRegex = /[A-Z]/
export const specialCharacterRegex = /[!@#$%^&*-]/
export const lowercaseRegex = /[a-z]/
export const digitRegex = /[0-9]/

interface IFormData {
	email: string
}

const ResendPassword = () => {
	const [errorMessage, setErrorMessage] = useState<string | null>(null)
	const router = useRouter()
	const [form] = Form.useForm<IFormData>();
	const [loading, setLoading] = useState(false)
	
	const handleSubmit = async (values: IFormData ) => {
		setErrorMessage(null)
		setLoading(true)

		const {email} = values

		await axiosInstance
		.post(`${process.env.AUTH_API_URL}/user/resend-activation-link`, {
			email,
		}, {
			withCredentials: true,
		})
		.then(async (res) => {
			if ( res.status === 200 ) {
				router.replace('/signup#verification')
			}
		})
		.catch((err) => {
			rollbar.error('Failed to resend password', err)
			setErrorMessage('Failed to resend password')
			setLoading(false)
		})
	}

	return (
		<FlowLayout
			title="This activation link has expired"
			hideLogos
		>
			<Form
				form={form}
				layout="vertical"
				autoComplete="off"
				noValidate
				style={{width: '100%'}}
				onFinish={handleSubmit}
			>
				<Wrapper>
					<InfoBox
						text="This activation link is no longer valid. Please enter your email below and we’ll send you a new activation link."
						variant='red'
					/>
					<SectionHeader>
						Enter work email
					</SectionHeader>
					<TextInput
						ariaLabel='email input'
						placeholder='john@example.com'
						disabled={loading}
						validateTrigger={['onSubmit']}
						onInputChange={() => {
							form.setFields([{
								name: 'email',
								errors: []
							}])
						}}
						name="email" 
						rules={
							[
								{
									validator: (_: unknown, value: string) => {
										if (!value?.length) {
											focusInput('email')
											return Promise.reject(new Error('A valid work email is required'))
										}
										if (value.length < 3) {
											focusInput('email')
											return Promise.reject(new Error('Email should contain at least 3 characters.'))
										}
										if (value.length > 254) {
											focusInput('email')
											return Promise.reject(new Error('Email should contain at most 254 characters.'))
										}
										if (!emailRegex.test(value)) {
											focusInput('email')
											return Promise.reject(new Error("Email field only accepts the following characters: alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), and spaces."))
										}
										return Promise.resolve()
									}
								}
							]}
					/>
					{errorMessage && (
						<ErrorText>
							{errorMessage}
						</ErrorText>
					)}
				</Wrapper>
				<FlowNavButtons
					primaryText="Send new activation link"
					loading={loading}
				/>
			</Form>
		</FlowLayout>
	)
}

export default ResendPassword
